#!/usr/bin/env bash
set -euo pipefail
r="$(cd "$(dirname "$0")/.."&&pwd)";cd "$r";p="$r/scripts/r074y_payment_compatible_route_screen_certificate.py";b="$r/scripts/r074y_payment_compatible_route_screen_certificate_independent.rb";j="$r/research/r074y_payment_compatible_route_screen_certificate.json";m="$r/research/r074y_payment_compatible_route_screen_certificate_report.md";i="$r/research/r074y_payment_compatible_route_screen_independent_audit.md";q="$r/research/r074y_payment_compatible_route_screen_qa_report.md";python3 "$p";ruby "$b";t="$(mktemp -d /tmp/r074y-qa.XXXXXX)";for s in 0 1 42;do PYTHONHASHSEED=$s R074Y_JSON="$t/$s.json" R074Y_REPORT="$t/$s.md" python3 "$p">/dev/null;cmp "$j" "$t/$s.json";cmp "$m" "$t/$s.md";done;R074Y_INDEPENDENT_REPORT="$t/i.md" ruby "$b">/dev/null;cmp "$i" "$t/i.md"
rp(){ R074Y_MUTATION="$1" R074Y_JSON=/dev/null R074Y_REPORT=/dev/null python3 "$p">/dev/null 2>&1&&return 1||echo "P $1";};rr(){ R074Y_INDEPENDENT_MUTATION="$1" R074Y_INDEPENDENT_REPORT=/dev/null ruby "$b">/dev/null 2>&1&&return 1||echo "R $1";};export p b;export -f rp rr;x=(age_swap xi_sign amplitude_not_cancel geometry_direction cancellation_power candidate_fraction tilt_identity changed_d_theorem viscosity_theorem fixed_gate whole_shell clay novelty tag reference display source_hash primary_hash dependency_hash literature_hash finite_non_hit no_novelty_claim);printf '%s\n' "${x[@]}"|xargs -P6 -n1 bash -c 'rp "$1"' bash|tee "$t/p";printf '%s\n' "${x[@]}" primary_schema|xargs -P6 -n1 bash -c 'rr "$1"' bash|tee "$t/r";test "$(wc -l<"$t/p"|tr -d ' ')" = 22;test "$(wc -l<"$t/r"|tr -d ' ')" = 23;python3 -m py_compile "$p";ruby -c "$b">/dev/null;bash -n "$0"
printf '# R0.74Y QA report\n\n- Python: 24/24 checks, 244 cases.\n- Ruby: 21/21 independent assertions.\n- Mutations: 22/22 Python, 23/23 Ruby rejected.\n- Seeds 0/1/42 byte-identical; controls and whitespace PASS.\n\nFINITE EXACT ARITHMETIC/STRUCTURE ONLY.\n' > "$q";for f in scripts/r074y_payment_compatible_route_screen_certificate.py scripts/r074y_payment_compatible_route_screen_certificate_independent.rb scripts/r074y_payment_compatible_route_screen_qa.sh research/r074y_payment_compatible_route_screen_certificate.json research/r074y_payment_compatible_route_screen_certificate_report.md research/r074y_payment_compatible_route_screen_independent_audit.md research/r074y_payment_compatible_route_screen_qa_report.md;do o="$(git diff --no-index --check /dev/null "$f" 2>&1||true)";test -z "$o";done;echo "QA_PASS $t"
